VID.narration = {"look":{"bar":false},"scenes":[{"dur":10.96,"caps":[[0.5,9.55,"Lecture fifteen. Multi-objective particle swarm optimisation. This is how a swarm keeps a whole front of good trade-offs."]],"warp":[[0,0],[0.5,0.9],[10.96,4]]},{"dur":26.68,"caps":[[0.5,7.15,"Nine drone routes, each scored by time and energy. Lower is better."],[7.4,15.01,"Plain PSO follows two points: its own pbest and the swarm's gbest."],[15.26,20.71,"Five routes are not dominated by any other route."],[20.96,25.77,"None beats the other four, so there is no single gbest."]],"warp":[[0,0],[0.5,0.5],[7.4,3.2],[15.26,6],[20.96,8.8],[26.68,12]]},{"dur":36.757,"caps":[[0.5,7.39,"A particle's pbest starts at (5, 5). Lower time and energy are better."],[7.64,14.29,"It moves to (4, 6), a trade-off. Keep oldest stays, keep newest moves."],[14.54,21.35,"(6, 7) is worse on both goals, so neither rule moves."],[21.6,27.93,"(3.5, 5.5) is another trade-off: only keep newest moves."],[28.18,34.83,"(4.5, 4) dominates (5, 5), so now keep oldest moves too."]],"warp":[[0,0],[0.5,0.5],[7.64,3.2],[14.54,6.6],[21.6,9.2],[28.18,12],[36.757,15]]},{"dur":36.571,"caps":[[0.5,6.35,"The archive keeps every non-dominated route found so far."],[6.6,14.21,"Newcomer (2, 4) dominates two members: they leave and it joins."],[14.46,21.83,"(5, 4.5) is dominated by (2, 4), so it is turned away."],[22.08,29.77,"(7, 2) is a new trade-off: nobody dominates it, so it joins."],[30.02,35.15,"No member dominates another: the archive is the front so far."]],"warp":[[0,0],[0.5,0.5],[6.6,3.2],[14.46,6.8],[22.08,10.2],[30.02,13.4],[36.571,16]]},{"dur":31.649,"caps":[[0.5,4.51,"Twelve archive members, but the cap is six."],[4.76,12.37,"The two ends, a and l, get infinite crowding distance: always kept."],[12.62,20.87,"Remove the most crowded, j at 0.13, then recompute: f goes next."],[21.12,25.13,"Then c, k, g and b, one at a time."],[25.38,30.75,"Six spread-out members are left, ends included."]],"warp":[[0,0],[0.5,0.5],[4.76,3.2],[12.62,5.8],[21.12,9.2],[25.38,12.6],[31.649,15]]},{"dur":43.352,"caps":[[0.5,3.87,"Each particle (blue) needs a leader from the archive (green)."],[4.12,10.61,"Simplest: pick a member at random, each with a 1 in 5 chance."],[10.86,18.39,"Or count the particles each member dominates: c dominates four, e one."],[18.64,26.49,"Fewer means more likely to lead: e's weight is 1/2, c's only 1/5."],[26.74,33.39,"Or use particle P as the reference point: b, c and d dominate it."],[33.64,41.41,"Their own boxes: b 1.5, c 4, d 1.5. c covers most, so c leads."]],"warp":[[0,0],[0.5,0.5],[4.12,3.2],[10.86,6.2],[18.64,9.6],[26.74,12.2],[33.64,14.6],[43.352,17]]},{"dur":26.726,"caps":[[0.5,7.63,"A real run: ten drone routes (blue) and their archive (green)."],[7.88,13.89,"Each step the particles follow leaders, and better routes enter the archive."],[14.14,20.15,"The archive creeps towards the true front, the dashed line."],[20.4,24.73,"Capped at ten, it stays spread along the whole front."]],"warp":[[0,0],[0.5,0.5],[7.88,3.2],[14.14,7],[20.4,10.5],[26.726,13]]},{"dur":27.028,"caps":[[0.5,6.91,"Around a point, a quarter of space is better on both goals, a quarter worse."],[7.16,11.97,"The other half is neither: those points cannot be compared."],[12.22,19.03,"Each extra goal halves the share you can compare: 1/32 with six."],[19.28,25.45,"So almost every pair is non-dominated, and dominance stops ranking."]],"warp":[[0,0],[0.5,0.5],[7.16,3.4],[12.22,6],[19.28,9.6],[27.028,14]]},{"dur":15,"caps":[],"warp":[[0,0],[0.5,0.9],[4.28,2],[9.66,3.1],[15,9]]}]};
